    "drugBName": "Carvedilol",
    "severity": "Moderate",
    "mechanismCategory": "Metabolism",
    "mechanism": "Inhibisi isoenzim sitokrom P450 hepar (CYP3A4, CYP2C9, atau CYP2C19) oleh salah satu obat memperlambat klirens metabolik obat pasangan.",
    "clinicalOutcome": "Peningkatan kadar plasma dan bioavailabilitas obat substrat, meningkatkan risiko efek samping sedang.",
