    "drugBName": "Ferric carboxymaltose",
    "severity": "Moderate",
    "mechanismCategory": "Others",
    "mechanism": "Interaksi farmakologis tingkat sedang antara Captopril dan Ferric carboxymaltose sesuai dokumentasi DDInter 2.0.",
    "clinicalOutcome": "Modulasi efektivitas terapi atau peningkatan risiko efek samping moderat.",
    "management": "Lakukan pemantauan klinis teratur; sesuaikan dosis jika terdapat keluhan pada pasien.",
